Source code in <code>src/openkarst/visualization/openkarst_viewer.py</code> <pre><code>def _number_value(value, default=1.0, minimum=None):
    try:
        result = float(value)
    except (TypeError, ValueError):
        result = float(default)
    if not np.isfinite(result):
        result = float(default)
    if minimum is not None:
        result = max(float(minimum), result)
    return result
